def test_z_timestamps_are_parsed_as_utc() -> None:
    submission = Submission()

    submission.set_attributes({"created_at": "2024-12-09T17:22:55.662Z"})

    assert submission.created_at is not None
    assert submission.created_at.tzinfo is timezone.utc


def test_invalid_encoded_value_is_preserved() -> None:
    submission = Submission(stdout="not base64")

    assert submission.stdout == "not base64"


def test_as_body_rejects_missing_source_code() -> None:
    client = Mock(spec=Client)
    client.get_language_id.return_value = 100

    with pytest.raises(ValueError, match="source_code must be provided"):
        Submission().as_body(cast(Client, client))


def test_batch_tokens_are_stringified() -> None:
    submission = Submission(token=UUID("5513d8ca-975b-4499-b54b-342f1952d00e"))
    transport = Mock()
    response = Mock()
    response.json.return_value = {"submissions": [{}]}
    transport.get.return_value = response
    client = Client.__new__(Client)
    client.client = transport
    client.headers = {}

    client.get_submissions([submission])

    assert transport.get.call_args.kwargs["params"]["tokens"] == str(submission.token)


def test_batch_tokens_reject_missing_values() -> None:
    client = Client.__new__(Client)
    client.client = Mock()
    client.headers = {}

    with pytest.raises(ValueError, match="token"):
        client.get_submissions([Submission()])


def test_status_before_and_after_submission(request: pytest.FixtureRequest) -> None:
    client: Client = request.getfixturevalue("ce_client")
    submission = Submission(
        source_code='print("Hello World!")', language=LanguageAlias.PYTHON
    )

    assert submission.status is None

    client.create_submission(submission)
    client.get_submission(submission)

    assert isinstance(submission.status, Status)
    assert submission.status >= Status.IN_QUEUE


def test_is_done(request: pytest.FixtureRequest) -> None:
    client: Client = request.getfixturevalue("ce_client")
    submission = Submission(
        source_code='print("Hello World!")', language=LanguageAlias.PYTHON
    )

    assert submission.status is None

    client.create_submission(submission)
    wait(client=client, submissions=submission)

    assert submission.is_done()


def test_language_before_and_after_execution(request: pytest.FixtureRequest) -> None:
    client: Client = request.getfixturevalue("ce_client")
    code = """\
    public class Main {
        public static void main(String[] args) {
            System.out.println("Hello World");
        }
    }
    """

    submission = Submission(
        source_code=code,
        language=LanguageAlias.JAVA,
    )

    assert submission.language == LanguageAlias.JAVA
    submission = run(client=client, submissions=submission)
    assert submission.language == LanguageAlias.JAVA


def test_language_executable(request: pytest.FixtureRequest) -> None:
    client: Client = request.getfixturevalue("ce_client")
    code = b64decode(
        ""
    )
    submission = Submission(
        source_code=code,
        language=LanguageAlias.EXECUTABLE,
    )

    assert submission.language == LanguageAlias.EXECUTABLE
    submission = run(client=client, submissions=submission)
    assert submission.language == LanguageAlias.EXECUTABLE
    assert submission.stdout == "hello, world\n"
